function sname(d, i) { const s = d.stores[i]; return s.approx ? s.short || s.name.replace(/\s*\(approx\.\)/, "") : s.short || s.name; }
function link(d, o) { const s = d.stores[o[0]]; if (typeof o[3] === "string" && /^https?:/.test(o[3])) return o[3]; return s.link && o[3] != null ? s.link.replace("{id}", o[3]) : s.site || null; }
