const cap = s => { s = String(s); return s.charAt(0).toUpperCase() + s.slice(1); };
const full = p => p[0] + (p[1] && !/\d/.test(p[0]) && !String(p[0]).includes(p[1]) ? ", " + p[1] : "");
function choiceLine(d, i, n) { const p = d.items[i]; const real = p[5].filter(o => !d.stores[o[0]].approx); return n + ". " + full(p) + (real.length ? " (from " + money(real[0][1]) + ")" : ""); }

// ---- list (basket)
function cost(o, q) { const reg = o[2] || o[1]; if (o[4] > 1) { const g = Math.floor(q / o[4]); return g * o[5] + (q - g * o[4]) * reg; } return o[1] * q; }
function parseList(text) {
  return text.split(/\n|;/).map(l => l.replace(/^\s*(?:[-•*·▪︎]+|\d+[.)])\s*/, "").trim()).filter(l => l && !/^(shopping\s+)?list:?$/i.test(l)).slice(0, MAX_LIST).map(l => {
    let q = 1, m;
    if ((m = l.match(/^(\d{1,2})\s*(?:x\s+|\s+)(?!(?:oz|lb|lbs|ct|pk|pack|gal|qt|l|ml|g|kg|%|fl)\b)(.+)$/i))) { q = +m[1]; l = m[2]; }
    else if ((m = l.match(/^(.+?)\s*[x×]\s*(\d{1,2})$/i))) { l = m[1]; q = +m[2]; }
    return { q: l.trim(), qty: Math.max(1, Math.min(q, 50)) };
  });
}
function listResult(d, list) {
  const rows = list.map(x => ({ ...x, i: find(d, x.q, 1)[0] }));
  const real = d.stores.map((s, i) => i).filter(i => !d.stores[i].approx);
  const tot = real.map(si => ({ si, total: 0, missing: [] }));
  let split = 0; const usedStores = new Set();
  for (const r of rows) {
    if (r.i == null) continue; const p = d.items[r.i]; const by = {};
    p[5].forEach(o => { if (!d.stores[o[0]].approx) by[o[0]] = o; });
    const best = Object.values(by).map(o => [o, cost(o, r.qty)]).sort((a, b) => a[1] - b[1])[0];
    if (best) { r.best = best; split += best[1]; usedStores.add(best[0][0]); }
    const ax = p[5].filter(o => d.stores[o[0]].approx).sort((a, b) => a[1] - b[1])[0]; if (ax) r.ax = ax;
    tot.forEach(t => { const o = by[t.si]; if (o) t.total += cost(o, r.qty); else t.missing.push(p[0].split(",")[0]); });
  }
  tot.forEach(t => t.total = Math.round(t.total * 100) / 100);
  tot.sort((a, b) => (a.missing.length - b.missing.length) || (a.total - b.total));
  return { rows, tot, split: Math.round(split * 100) / 100, usedStores: [...usedStores] };
}
function listReply(d, list, city) {
  const r = listResult(d, list); const L = ["*Your list* · " + city.short]; const used = [];
  for (const x of r.rows) {
    if (x.i == null) { L.push("• " + x.q + ": not found, try other words"); continue; }
    const p = d.items[x.i];
    L.push("• " + (x.qty > 1 ? x.qty + " × " : "") + full(p) + ": " + (x.best ? money(x.best[1]) + " " + sname(d, x.best[0][0]) : "no price") + (x.ax && x.best && cost(x.ax, x.qty) < x.best[1] ? " (≈ " + money(cost(x.ax, x.qty)) + " " + sname(d, x.ax[0]) + ", approx.)" : ""));
    if (x.best) used.push(x.best[0][0]); if (x.ax) used.push(x.ax[0]);
  }
  const found = r.rows.filter(x => x.i != null);
  if (found.length) {
    const b = r.tot.filter(t => t.total > 0).slice(0, 3);
    if (b.length) {
      L.push(""); L.push("*Best single store:* " + sname(d, b[0].si) + " " + money(b[0].total) + (b[0].missing.length ? " (doesn't have: " + miss(b[0].missing) + ")" : " (has everything)"));
      b.slice(1).filter(t => t.missing.length <= b[0].missing.length + 1).forEach((t, n) => L.push((n === 0 ? "Next: " : "Then: ") + sname(d, t.si) + " " + money(t.total) + (t.missing.length ? " (doesn't have: " + miss(t.missing) + ")" : "")));
      if (r.usedStores.length > 1) L.push("Cheapest of each item, across stores: " + money(r.split));
    }
    if (d.stores.some(s => s.approx)) L.push("≈ approx. stores (" + d.stores.filter(s => s.approx).map(s => sname(d, d.stores.indexOf(s))).join(", ") + ") are not in the totals: estimates, not from a store website.");
    L.push("Multi-buy deals count when your quantity reaches them. Fees and minimums not included.");
    L.push(readLine(d, used));
  }
  return { text: L.join("\n"), result: r };
}
function miss(a) { return a.length <= 2 ? a.join(", ") : a.slice(0, 2).join(", ") + " and more"; }

// ---- sales
function salesReply(sd, city, store) {
  const today = new Date().toLocaleDateString("en-CA", { timeZone: "America/New_York" });
  let s = (sd.sales || []).filter(x => !x.valid_to || x.valid_to >= today);
  if (store) s = s.filter(x => norm(x.store).includes(norm(store)));
  if (!s.length) return "No current sales found" + (store ? " at " + store : "") + " in " + city.short + ". All prices: " + city.web;
  const L = ["*Sales this week* · " + city.short];
  s.slice(0, 8).forEach(x => L.push("• " + x.product + ": " + (x.deal ? x.deal : money(x.sale_price) + (x.per_lb ? "/lb" : "")) + " at " + x.store + " (reg " + money(x.regular_price) + (x.per_lb ? "/lb" : "") + ", " + x.pct_off + "% off" + (x.valid_to ? ", until " + day(x.valid_to + "T12:00:00Z") : "") + ")"));
  const rd = s.slice(0, 8).map(x => x.checked).filter(Boolean).sort()[0];
  L.push("Real sales only: each store's own sale price vs its own regular price.");
  L.push("All sales: " + city.web + "?tab=sales");
  L.push((rd && ageDays(rd) > STALE_DAYS ? "⚠️ Older read (" + day(rd) + "). " : "Read " + (rd ? day(rd) : "recently") + ". ") + "Confirm in store.");
  return L.join("\n");
}

// ---- conversation
const CITY_MENU = cs => "Which area do you shop in? Reply with a number:\n" + cs.map((c, n) => (n + 1) + ". " + c.name).join("\n");
function cityIn(cs, text) {
  const t = " " + norm(text) + " "; let best = null, len = 0;
  for (const c of cs) for (const w of c.words) { if (t.includes(" " + w + " ") && w.length > len) { best = c; len = w.length; } }
  return best;
}
function stripCity(cs, text, c) { let t = " " + norm(text) + " "; if (c) for (const w of c.words.slice().sort((a, b) => b.length - a.length)) t = t.split(" in " + w + " ").join(" ").split(" " + w + " ").join(" "); return t.trim(); }
const HELP = cs => "*Click613 grocery prices* 🛒\nCompare kosher grocery prices: " + cs.map(c => c.short).join(", ") + ".\n\n• An item: *milk price* or *where is milk cheapest*\n• Another area: *eggs price Monsey*\n• Your list: send items, one per line\n• Sales: *sales this week*\n• Change area: *area Monsey*";
const CHAT = /^(hi|hey|hello|yes|no|ok|okay|thanks|thank you|thx|good|great|cool|bye|shalom|gut|amazing|perfect|wow|lol|who|what|why|when)\b/;
// a price word anywhere ("where is milk cheapest in Lakewood", "milk price lakewood", "compare challah prices"): answered only when an item matches
const INTENT = /\b(price|prices|pricing|priced|cost|costs|how much|cheapest|cheaper|cheap|lowest|compare|comparison|best price|best deal)\b/;
const QDROP = new Set(["where", "wheres", "is", "are", "can", "could", "i", "we", "get", "buy", "find", "the", "price", "prices", "pricing", "priced", "cost", "costs", "how", "much", "cheapest", "cheaper", "cheap", "lowest", "best", "deal", "compare", "comparison", "which", "store", "stores", "has", "have", "sells", "sell", "carries", "what", "whats", "of", "for", "in", "at", "a", "an", "does", "do", "to", "today", "now", "please", "pls", "plz", "me", "my", "who", "whos", "there", "by", "on", "near", "nearby", "around", "here", "right", "currently", "this", "week", "is?"]);
const cleanQ = s => norm(s).split(" ").filter(w => w && !QDROP.has(w)).join(" ");
const TRIGGER = /^(price|prices|pricing|cost|how much|cheapest|cheaper|best price|where( can i| is| are)?( the)? cheapest|lowest price|compare|grocery|groceries|shopping|shopping list|my list|list|sales?|deals?|specials?)\b/i;

async function converse(env, o, text, state, force) {
  const cs = await cities(env, o); state = (state && typeof state === "object") ? state : {};
  const now = Date.now(); const active = state.t && now - state.t < ACTIVE_MIN * 60e3;
  const raw = String(text || "").trim(); const t = norm(raw); const lines = raw.split(/\n/).map(x => x.trim()).filter(Boolean);
  const out = (reply, kind, extra = {}) => ({ handled: true, kind, reply, state: { ...state, ...extra.state, t: now }, ...(extra.data ? { data: extra.data } : {}) });
  if (!t) return { handled: false, state };
  if (/^(menu|main menu|exit|stop|quit|back|cancel|0)$/.test(t)) { const s = { city: state.city }; return { handled: false, state: s }; }
  // pending answers
  if (state.pending && /^\d{1,2}$/.test(t)) {
    const n = +t;
    if (state.pending.type === "city" && cs[n - 1]) { const c = cs[n - 1]; const pend = state.pending.text; state = { city: c.key };
      if (pend) { const r = await converse(env, o, pend, state, true); r.reply = "Got it: " + c.short + ". (Change anytime: *area <name>*)\n\n" + r.reply; return r; }
      return out("Got it: " + c.short + ". Ask me any item, send a list, or *sales this week*.", "city_set", { state: { city: c.key, pending: null } }); }
    if (state.pending.type === "pick" && state.pending.choices && state.pending.choices[n - 1]) {
      const ck = state.pending.city || state.city; const c = cs.find(x => x.key === ck); const d = await index(env, o, ck);
      const want = state.pending.choices[n - 1]; const i = d.items.findIndex(p => p[0] === want);
      if (i >= 0) return out(itemReply(d, i, c), "item", { state: { pending: null }, data: itemJSON(d, i) });
    }
  }
  if (/^\d{1,2}$/.test(t)) return out(state.pending && state.pending.type === "pick" ? "Reply " + state.pending.choices.map((x, n) => n + 1).slice(1).join(" or ") + " to pick one of the items above, or type an item." : state.pending && state.pending.type === "city" ? CITY_MENU(cs) : "Type an item (e.g. *price of tuna*), send a list, or *sales this week*.", "hint");
  // set the area
  let m = raw.match(/^(?:my\s+)?(?:city|area|town|neighbou?rhood|location)\s*(?:is|=|:)?\s*(.*)$/i) || raw.match(/^change\s+(?:city|area)\s*(.*)$/i);
  if (m) { const c = cityIn(cs, m[1] || "");
    if (c) return out("Got it: " + c.short + ". Ask me any item, send a list, or *sales this week*.", "city_set", { state: { city: c.key, pending: null } });
    return out(CITY_MENU(cs), "ask_city", { state: { pending: { type: "city" } } }); }
  const isList = lines.length >= 2 || /^(shopping\s+)?list\s*:/i.test(raw);
  const trig = TRIGGER.test(t) || TRIGGER.test(raw);
  const intent = !isList && !trig && INTENT.test(t);
  const weak = !isList && !trig && !intent && !force;
  if (!isList && !trig && !intent && !force && !active && !state.pending) return { handled: false, state };
  if (/^(grocery|groceries|grocery prices|prices|help|shopping)$/.test(t)) return out(HELP(cs), "help");
  // which area
  const named = cityIn(cs, isList ? lines[0] : raw);
  let ck = named ? named.key : state.city, dflt = false;
  if (!ck && cs.some(c => c.key === "lakewood")) { ck = "lakewood"; dflt = true; }   // no area named or saved: Lakewood (not saved to state)
  if (!ck) return out(CITY_MENU(cs), "ask_city", { state: { pending: { type: "city", text: raw } } });
  const city = cs.find(c => c.key === ck); const keep = (state.city || dflt) ? {} : { city: ck };
  const dnote = dflt ? "\n(Lakewood prices. Other area? Add the town, e.g. *eggs price Monsey*)" : "";
  // sales
  if (!isList && /\b(sales?|deals?|specials?|on sale)\b/.test(t)) {
    const sd = await sales(env, o, ck); const st = (raw.match(/\bat\s+([a-z0-9 &'.-]+)$/i) || [])[1];
    return out(salesReply(sd, city, st && !cityIn(cs, st) ? st : null), "sales", { state: { ...keep, pending: null } });
  }
  const d = await index(env, o, ck);
  if (isList) {
    let ls = raw.replace(/^(shopping\s+)?list\s*:\s*/i, ""); if (lines.length < 2) ls = ls.split(/,/).join("\n");
    if (named) ls = ls.split("\n").filter((l, n) => !(n === 0 && cityIn(cs, l) && norm(stripCity(cs, l, named)).length < 3)).join("\n");
    const r = listReply(d, parseList(ls), city);
    return out(r.text, "list", { state: { ...keep, pending: null }, data: { totals: r.result.tot.slice(0, 6).map(t => ({ store: d.stores[t.si].name, total: t.total, missing: t.missing })), across_stores: r.result.split,
      items: r.result.rows.map(x => ({ asked: x.q, qty: x.qty, matched: x.i == null ? null : d.items[x.i][0] })) } });
  }
  // single item
  let q = stripCity(cs, raw, named).replace(/^(what('?s| is)? the )?(price|prices|pricing|cost) (of |for )?/, "").replace(/^how much (is|are|does|do|for) (a |an |the )?/, "").replace(/^(where (can i get|is|are) (the )?)?(cheapest|cheaper|lowest price( of| for)?|best price( of| for)?|compare) /, "").replace(/\b(cost|costs)$/, "").trim();
  q = cleanQ(q) || q;
  if (!terms(q).length) return intent ? { handled: false, state } : out(HELP(cs), "help");
  const hits = find(d, q, 4);
  if (intent && !hits.length) return { handled: false, state: { ...state, pending: null } };   // a price word but no grocery item: leave it to the bot
  const tq1 = terms(q);
  if (hits.length && tq1.length === 1 && !hits.some(i => endsWithTerm(d.items[i], tq1[0]))) {   // "eggs" but only "egg noodles" in this area: say so, offer the closest
    return out("No plain \"" + q + "\" price listed in " + city.short + ". Closest, reply a number:\n" + hits.slice(0, 3).map((i, n) => choiceLine(d, i, n + 1)).join("\n") + dnote, "closest",
      { state: { ...keep, pending: { type: "pick", city: ck, choices: hits.slice(0, 3).map(i => d.items[i][0]) } } });
  }
  if (weak) {   // only "active" (a grocery chat in the last minutes), no trigger word: answer only a clear item name, else let the bot carry on
    const tt = terms(q), nm0 = hits.length ? " " + norm(d.items[hits[0]][0]) + " " : "";
    const clear = hits.length && tt.length <= 5 && tt.every(a => a.some(x => nm0.includes(" " + x + " ") || nm0.includes(" " + x + "s ")));
    if (!clear || CHAT.test(t)) return { handled: false, state: { ...state, pending: null } };
  }
  if (!hits.length && terms(q).length > 1) {   // closest: drop one word at a time (often the brand)
    const ws = norm(q).split(" ").filter(x => !STOP.has(x)); let near = [];
    for (let k = 0; k < ws.length && !near.length; k++) near = find(d, ws.filter((_, j) => j !== k).join(" "), 3);
    if (near.length) return out("No exact match for \"" + q + "\" in " + city.short + ". Closest, reply a number:\n" + near.map((i, n) => choiceLine(d, i, n + 1)).join("\n"), "closest",
      { state: { ...keep, pending: { type: "pick", city: ck, choices: near.map(i => d.items[i][0]) } } });
  }
  if (!hits.length) return out("No match for \"" + q + "\" in " + city.short + ". Try fewer or other words (brand + item, e.g. *Gefen tuna*). All prices: " + city.web, "no_match", { state: { ...keep, pending: null } });
  let reply = itemReply(d, hits[0], city) + dnote;
  const more = hits.slice(1, 3);
  if (more.length) reply += "\n\nNot this one? Reply a number:\n" + more.map((i, n) => choiceLine(d, i, n + 2)).join("\n");
  return out(reply, "item", { state: { ...keep, pending: more.length ? { type: "pick", city: ck, choices: [d.items[hits[0]][0], ...more.map(i => d.items[i][0])] } : null }, data: itemJSON(d, hits[0]) });
}

// ---- eruv lookup (point in polygon; never says "outside" — only "no drawn boundary found here")
function inRing(x, y, r) { let c = false; for (let i = 0, j = r.length - 1; i < r.length; j = i++) { const [xi, yi] = r[i], [xj, yj] = r[j]; if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) c = !c; } return c; }
function inPoly(x, y, rings) { if (!inRing(x, y, rings[0])) return false; for (let k = 1; k < rings.length; k++) if (inRing(x, y, rings[k])) return false; return true; }
function km(a, b, c, d) { const R = 6371, r = Math.PI / 180, x = (d - b) * r * Math.cos((a + c) / 2 * r), y = (c - a) * r; return Math.sqrt(x * x + y * y) * R; }
function bbox(g) { let a = [180, 90, -180, -90]; const w = c => { if (typeof c[0] === "number") { a = [Math.min(a[0], c[0]), Math.min(a[1], c[1]), Math.max(a[2], c[0]), Math.max(a[3], c[1])]; } else c.forEach(w); }; w(g.coordinates); return a; }
async function eruv(env, o, lat, lng) {
  if (!ERUV) ERUV = await asset(env, o, "/eruv/eruvin.geojson");
  const inside = [], near = [];
  for (const f of ERUV.features) {
    const g = f.geometry, p = f.properties || {}; if (!g) continue;
    const info = { id: p.id, name: p.name, city: p.city || p.town, hotline: p.hotline || null, contacts: p.contacts || null, auspices: p.auspices || null, approximate: String(p.approximate) === "True" || p.approximate === true, kind: p.kind };
    if (g.type === "Polygon" && inPoly(lng, lat, g.coordinates)) inside.push(info);
    else if (g.type === "MultiPolygon" && g.coordinates.some(r => inPoly(lng, lat, r))) inside.push(info);
    else if (g.type === "Point") { const k = km(lat, lng, g.coordinates[1], g.coordinates[0]); if (k < 3) near.push({ ...info, km: Math.round(k * 10) / 10 }); }
    else if (/LineString/.test(g.type)) { const b = bbox(g); if (lng >= b[0] - 0.01 && lng <= b[2] + 0.01 && lat >= b[1] - 0.01 && lat <= b[3] + 0.01) near.push({ ...info, km: null }); }
  }
  near.sort((a, b) => (a.km ?? 0) - (b.km ?? 0));
  const L = [];
  if (inside.length) { L.push("📍 Inside the drawn boundary of:"); inside.forEach(e => L.push("• *" + e.name + "*" + (e.hotline ? "\n  Check it's up: " + e.hotline : ""))); }
  else L.push("📍 No drawn eruv boundary found at this spot." + (near.length ? " It may still be covered by:" : ""));
  if (!inside.length) near.slice(0, 3).forEach(e => L.push("• " + e.name + (e.km != null ? " (~" + e.km + " km, approximate location)" : " (boundary drawn as lines only)") + (e.hotline ? "\n  " + e.hotline : "")));
  L.push("Always check the eruv is up before Shabbos and ask your Rav. Map: https://click613.com/eruv");
  return { lat, lng, inside, may_cover: near.slice(0, 5), whatsapp_text: L.join("\n"), source_built: ERUV.built };
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url), o = url.origin, P = url.pathname;
    if (req.method === "OPTIONS") return new Response(null, { headers: { ...H, "access-control-allow-methods": "GET,POST", "access-control-allow-headers": "content-type" } });
    if (!P.startsWith("/api/v1/")) {
      if (P === "/terms" || P === "/terms/" || P === "/disclaimer.html" || P === "/disclaimer") return new Response(TERMS_HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=900" } });
      const r = await env.ASSETS.fetch(req);
      if (/\.(json|geojson)$/.test(P) && r.ok) { const h = new Headers(r.headers); h.set("access-control-allow-origin", "*"); h.set("cache-control", "public, max-age=900"); h.set("link", "<" + TERMS.url + ">; rel=\"terms-of-service\""); if (P.endsWith(".geojson")) h.set("content-type", "application/geo+json"); return new Response(r.body, { status: r.status, headers: h }); }
      return r;
    }
    // the static files again, with CORS and a 15-minute cache (static assets are served without either)
    const pass = async (path, type) => { const r = await env.ASSETS.fetch(new Request(o + path)); if (!r.ok) return J({ error: "not found" }, 404);
      return new Response(r.body, { status: 200, headers: { ...H, "content-type": type, "cache-control": "public, max-age=900", link: "<" + TERMS.url + ">; rel=\"terms-of-service\"" } }); };
    if (P === "/api/v1/eruv.geojson") return pass("/eruv/eruvin.geojson", "application/geo+json; charset=utf-8");
    let dm = P.match(/^\/api\/v1\/data\/((?:[a-z]+\/)?(?:index|sales|cities)\.json)$/);
    if (dm) return pass("/api/" + dm[1], "application/json; charset=utf-8");
    try {
      let body = {}; if (req.method === "POST") body = await req.json().catch(() => ({}));
      const g = k => body[k] ?? url.searchParams.get(k);
      const cs = await cities(env, o);
      const cityKey = v => { if (!v) return null; const c = cs.find(x => x.key === String(v).toLowerCase()) || cityIn(cs, v); return c ? c.key : null; };
      if (P === "/api/v1/reply") {
        let st = g("state"); if (typeof st === "string") { try { st = JSON.parse(st); } catch (e) { st = {}; } }
        st = st || {}; const ck = cityKey(g("city")); if (ck && !st.city) st.city = ck;
        const force = g("force") === true || g("force") === "1" || g("force") === "true";
        return J(await converse(env, o, g("text") || g("q") || "", st, force));
      }
      if (P === "/api/v1/cities") return J({ cities: cs.map(c => ({ key: c.key, name: c.name, web: c.web, updated: c.updated, stores: c.stores, big_chains: c.big_chains, index: c.index, sales: c.sales })) }, 200, "public, max-age=900");
      const ck = cityKey(g("city"));
      if (["/api/v1/search", "/api/v1/list", "/api/v1/sales"].includes(P) && !ck) return J({ error: "add city= one of " + cs.map(c => c.key).join(", ") }, 400);
      const city = cs.find(c => c.key === ck);
      if (P === "/api/v1/search") {
        const q = (g("q") || "").trim(); if (!q) return J({ error: "add q=" }, 400);
        const d = await index(env, o, ck); const hits = find(d, q, Math.min(+g("limit") || 3, 10));
        return J({ city: ck, q, updated: d.updated, items: hits.map(i => itemJSON(d, i)), whatsapp_text: hits.length ? itemReply(d, hits[0], city) : "No match for \"" + q + "\" in " + city.short + "." }, 200, "public, max-age=600");
      }
      if (P === "/api/v1/list") {
        let items = body.items || (g("items") || "").split(/[,\n]/);
        const list = Array.isArray(items) ? items.filter(Boolean).slice(0, MAX_LIST).map(x => typeof x === "string" ? parseList(x)[0] : { q: x.q || x.name || "", qty: Math.max(1, +x.qty || 1) }).filter(x => x && x.q) : [];
        const d = await index(env, o, ck); const r = listReply(d, list, city);
        return J({ city: ck, updated: d.updated, items: r.result.rows.map(x => ({ asked: x.q, qty: x.qty, matched: x.i == null ? null : itemJSON(d, x.i), cheapest: x.best ? { store: d.stores[x.best[0][0]].name, cost: Math.round(x.best[1] * 100) / 100 } : null })),
          totals: r.result.tot.filter(t => t.total > 0).map(t => ({ store: d.stores[t.si].name, total: t.total, missing: t.missing })), across_stores: r.result.split,
          approx_excluded: d.stores.filter(s => s.approx).map(s => s.name), whatsapp_text: r.text });
      }
      if (P === "/api/v1/sales") { const sd = await sales(env, o, ck); return J({ city: ck, sales: sd.sales, rules: sd.rules, whatsapp_text: salesReply(sd, city, g("store")) }, 200, "public, max-age=900"); }
      if (P === "/api/v1/eruv") {
        const lat = +g("lat"), lng = +g("lng") || +g("lon"); if (!isFinite(lat) || !isFinite(lng) || (!lat && !lng)) return J({ error: "add lat= and lng=" }, 400);
        return J(await eruv(env, o, lat, lng), 200, "public, max-age=900");
      }
      return J({ error: "unknown endpoint", endpoints: ["POST /api/v1/reply {text, state}", "/api/v1/search?city=monsey&q=eggs", "POST /api/v1/list {city, items:[...]}", "/api/v1/sales?city=lakewood", "/api/v1/cities", "/api/v1/eruv?lat=40.09&lng=-74.21"] }, 404);
    } catch (e) { return J({ error: String(e && e.message || e) }, 500); }
  }
};
